import re

def validate_tags(tags):
    # Ensure tags are alphanumeric and separated by commas
    if not re.match(r'^[\w, ]*$', tags):
        raise ValueError("Invalid tags format")
    return [tag.strip() for tag in tags.split(',') if tag.strip()]

# Example usage
try:
    tags = validate_tags("tag1, tag2, tag3")
    print("Valid tags:", tags)
except ValueError as e:
    print("Error:", e)
